 80	interface SetLabelStyleOpt<TLabelDataIndex> extends TextCommonParams {
 81	    defaultText?: string | ((
 82	        labelDataIndex: TLabelDataIndex,
 83	        opt: SetLabelStyleOpt<TLabelDataIndex>,
 84	        interpolatedValue?: InterpolatableValue
 85	    ) => string);
 86	    // Fetch text by:
 87	    // opt.labelFetcher.getFormattedLabel(
 88	    //     opt.labelDataIndex, 'normal'/'emphasis', null, opt.labelDimIndex, opt.labelProp
 89	    // )
 90	    labelFetcher?: {
 91	        getFormattedLabel: (
 92	            // In MapDraw case it can be string (region name)
 93	            labelDataIndex: TLabelDataIndex,
 94	            status: DisplayState,
 95	            dataType?: string,
 96	            labelDimIndex?: number,
 97	            formatter?: string | ((params: object) => string),
 98	            // If provided, the implementation of `getFormattedLabel` can use it
 99	            // to generate the final label text.
100	            extendParams?: {
101	                interpolatedValue: InterpolatableValue
102	            }
103	        ) => string;
104	    };
105	    labelDataIndex?: TLabelDataIndex;
106	    labelDimIndex?: number;
107	
108	    /**
109	     * Inject a setter of text for the text animation case.
110	     */
111	    enableTextSetter?: boolean
112	}
113	type LabelModel = Model<LabelOption & {
