121	    }>;
122	
123	type LabelStatesModels<LabelModel> = Partial<Record<DisplayStateNonNormal, LabelModel>> & {normal: LabelModel};
124	
125	type LabelCommonModel<
126	    TNuance extends TextCommonOptionNuanceBase = TextCommonOptionNuanceDefault
127	> = Model<LabelCommonOption<TNuance>>;
