129	export function setLabelText(label: ZRText, labelTexts: Record<DisplayState, string>) {
130	    for (let i = 0; i < SPECIAL_STATES.length; i++) {
131	        const stateName = SPECIAL_STATES[i];
132	        const text = labelTexts[stateName];
133	        const state = label.ensureState(stateName);
134	        state.style = state.style || {};
135	        state.style.text = text;
136	    }
137	
138	    const oldStates = label.currentStates.slice();
139	    label.clearStates(true);
140	    label.setStyle({ text: labelTexts.normal });
141	    label.useStates(oldStates, true);
142	}
143	
144	function getLabelText<TLabelDataIndex>(
145	    opt: SetLabelStyleOpt<TLabelDataIndex>,
146	    stateModels: LabelStatesModels<LabelModel>,
147	    interpolatedValue?: InterpolatableValue
148	): Record<DisplayState, string> {
149	    const labelFetcher = opt.labelFetcher;
150	    const labelDataIndex = opt.labelDataIndex;
151	    const labelDimIndex = opt.labelDimIndex;
152	    const normalModel = stateModels.normal;
153	    let baseText;
154	    if (labelFetcher) {
155	        baseText = labelFetcher.getFormattedLabel(
156	            labelDataIndex, 'normal',
157	            null,
158	            labelDimIndex,
159	            normalModel && normalModel.get('formatter'),
160	            interpolatedValue != null ? {
161	                interpolatedValue
162	            } : null
163	        );
164	    }
165	    if (baseText == null) {
166	        baseText = isFunction(opt.defaultText)
167	            ? opt.defaultText(labelDataIndex, opt, interpolatedValue)
168	            : opt.defaultText;
169	    }
170	
171	    const statesText = {
172	        normal: baseText
173	    } as Record<DisplayState, string>;
174	
175	    for (let i = 0; i < SPECIAL_STATES.length; i++) {
176	        const stateName = SPECIAL_STATES[i];
177	        const stateModel = stateModels[stateName];
178	        statesText[stateName] = retrieve2(labelFetcher
179	            ? labelFetcher.getFormattedLabel(
180	                labelDataIndex,
181	                stateName,
182	                null,
183	                labelDimIndex,
184	                stateModel && stateModel.get('formatter')
185	            )
186	            : null, baseText);
187	    }
188	    return statesText;
189	}
