115	/**
116	 * Commonly used as `MatrixCoordRangeOption[]`
117	 * Can locate a cell or a rect range of cells.
118	 * `[2, 8]` indicates a cell.
119	 * `[2, null/undefined/NaN]` means y is the entire column.
120	 * `[null/undefined/NaN, 8]` is the opposite.
121	 * `[[2, 5], 8]` indicates a rect of cells in x range of `2~5` and y `8`.
122	 * `[[2, 5], null/undefined/NaN]` indicates a x range of `2~5` and y is the entire column.
123	 * `[[2, 5], [7, 8]]` indicates a rect of cells in x range of `2~5` and y range of `7~8`.
124	 * `['aNonLeaf', 8]` indicates a rect of cells in x range of `aNonLeaf` and y `8`.
125	 * @see {parseCoordRangeOption}
126	 * @see {MatrixBodyCornerBaseOption['data']}
127	 */
128	export type MatrixCoordRangeOption = (MatrixCoordValueOption | MatrixCoordValueOption[] | NullUndefined);
